#!/usr/bin/env node
/**
 * qpms.mjs — QPMS 工时(manHours)操作助手
 *
 * 通过 Kimi WebBridge 在同事本人已登录的浏览器里操作 qpms，
 * 所有 qpms 请求都在页面上下文内 fetch，自动读取本人的 quectel_token
 * 作为 Authorization 头 —— 绝不硬编码任何人的 token。
 *
 * 用法:
 *   node qpms.mjs status                     # 检查 WebBridge daemon + 扩展连接
 *   node qpms.mjs whoami                      # 打开 qpms，读取本人 token 与身份
 *   node qpms.mjs scan 2026-07 [2026-06 ...]  # 扫描月份，列出每天工时状态(需填/已满/非工作日)
 *   node qpms.mjs week 2026-07-06             # 查某周(含该日期的周一~周日)可填/禁填情况
 *   node qpms.mjs history                     # 最近常用的填报项(workItem)+ JIRA 历史选项
 *   node qpms.mjs fill '<editsJson>' [--submit] [--skip-filled] [--append]
 *                                            # 交互式填报(先删后插幂等替换),--submit 送审,--skip-filled 跳过已满天,--append 纯追加不先删
 *                                            # editsJson: [{"date":"2026-07-10","workItemId":"...","hours":8,"desc":"..."}]
 *   node qpms.mjs preview '<editsJson>'       # 只构造并打印某周报文,不保存(预演/诊断)
 *   node qpms.mjs del <date> [workItemId]     # 删除某天(某工作项)工时明细(纠错用)
 *   node qpms.mjs detect-browser              # 检测浏览器类型(Edge/Chrome/...)并给适配建议
 *   node qpms.mjs fill-direct '<editsJson>'   # 受限/超期天绕填:直接调 people-work 网关保存(绕过页面限制)
 *   node qpms.mjs submit-direct '<editsJson>' # 受限天送审:直接调 people-work 网关提交(需审批人工号 approveUserOne)
 *   node qpms.mjs modify '<editsJson>'        # 修改已有明细(UPDATE):必须带 workHoursId+hoursDetailId(从 scan 的 items 取),用于补差/改描述
 *   node qpms.mjs submit [2026-07 2026-06 ...] # 一键提交所有待提交(DRAFTS)草稿(按周安全送审,内置 8h 保护),默认当前月+上月
 *   node qpms.mjs hook-install                # 装网络拦截器(用于捕获 save/submit 真实报文)
 *   node qpms.mjs hook-dump                   # 导出捕获到的写接口报文
 *   node qpms.mjs api GET  <path>             # 通用带鉴权 GET (path 以 /api/ 开头)
 *   node qpms.mjs api POST <path> '<json>'    # 通用带鉴权 POST
 *
 * 环境变量:
 *   WB_PORT     WebBridge 端口(默认 10086)
 *   WB_SESSION  会话名(默认 qpms-worktime)
 */

const PORT = process.env.WB_PORT || '10086';
const SESSION = process.env.WB_SESSION || 'qpms-worktime';
const BASE = `http://127.0.0.1:${PORT}`;
const QPMS = 'https://qpms.quectel.com';
const CAL_URL = `${QPMS}/manHours/calendar`;

// —— QPMS 接口端点(project_url 基址 = /api/project/,均需 Authorization 头)——
const EP = {
  calendar:  '/api/project/v2/project/pork/qry/calendar',        // 整月日历
  specified: '/api/project/v1/project/pork/qr/fill/specified',   // 某周填报网格
  save:      '/api/project/v1/project/pork/batch/fill/save',      // 保存(草稿)  = $API.V1_PROJECT_PORK_BATCH_SAVE
  submit:    '/api/project/v1/project/pork/batch/fill',           // 提交(送审)  = $API.V1_PROJECT_PORK_BATCH
  jiraHist:  '/api/project/v1/project/pork/qr/history/option',    // JIRA 历史选项
  delDetail: '/api/people-work/v1/pork/del/detail',               // 删除单条明细(DELETE,body {workHoursDetailId})
  modify:    '/api/project/v2/project/pork/save',                 // 修改已有明细(UPDATE,必须带 workHoursId+hoursDetailId)
};

async function daemon(body) {
  const r = await fetch(`${BASE}/command`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ session: SESSION, ...body }),
  });
  const txt = await r.text();
  let j;
  try { j = JSON.parse(txt); } catch { throw new Error('daemon non-JSON: ' + txt.slice(0, 300)); }
  if (j.ok === false) throw new Error('daemon error: ' + JSON.stringify(j.error));
  return j;
}

async function status() {
  const r = await fetch(`${BASE}/status`);
  return await r.json();
}

async function navigate(url) {
  return (await daemon({ action: 'navigate', url })).data;
}

/** 在页面上下文执行 JS，返回解析后的返回值 */
async function evalCode(code) {
  const j = await daemon({ action: 'evaluate', code });
  const v = j?.data?.value;
  if (v === undefined) return j?.data;
  try { return JSON.parse(v); } catch { return v; }
}

/** 确保当前会话停在 qpms 工时页(同源 + 有 cookie)。
 *  若 session tab 已关闭(eval 报错),自动 navigate 重建——避免"session has no tab"中断整个命令。 */
async function ensureOnQpms() {
  let cur;
  try {
    cur = await evalCode('location.href');
  } catch (e) {
    cur = null; // tab 丢失/eval 失败 → 走下方重建
  }
  if (typeof cur !== 'string' || cur.indexOf('qpms.quectel.com') < 0) {
    await navigate(CAL_URL);
    await sleep(2500);
  }
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

/** 本地时区的 YYYY-MM-DD(避免 toISOString 的 UTC 偏移) */
function fmtLocal(x) {
  const y = x.getFullYear();
  const m = ('0' + (x.getMonth() + 1)).slice(-2);
  const d = ('0' + x.getDate()).slice(-2);
  return `${y}-${m}-${d}`;
}

/**
 * 生成一段"带鉴权 fetch"的页面 JS。method/path/body 通过 JSON 注入，安全无转义问题。
 */
function authFetchCode(method, path, body) {
  const p = JSON.stringify(path);
  const m = JSON.stringify(method);
  const b = body === undefined || body === null ? 'null' : JSON.stringify(JSON.stringify(body));
  return `(async function(){
    var token=(document.cookie.match(/quectel_token=([^;]+)/)||[])[1]||'';
    if(!token) return JSON.stringify({__err:'NO_TOKEN',hint:'请先在浏览器登录 qpms.quectel.com'});
    var opt={method:${m},headers:{'Accept':'application/json','Authorization':token},credentials:'include'};
    var raw=${b};
    if(raw!=null){opt.headers['Content-Type']='application/json';opt.body=raw;}
    try{
      var r=await fetch(${p},opt);
      var t=await r.text();
      var data; try{data=JSON.parse(t);}catch(e){data=t;}
      return JSON.stringify({__status:r.status,data:data});
    }catch(e){return JSON.stringify({__err:String(e)});}
  })()`;
}

async function apiCall(method, path, body) {
  await ensureOnQpms();
  const res = await evalCode(authFetchCode(method, path, body));
  return res;
}

// ---------- 业务命令 ----------

async function whoami() {
  await navigate(CAL_URL);
  await sleep(2500);
  const info = await evalCode(`(function(){
    var token=(document.cookie.match(/quectel_token=([^;]+)/)||[])[1]||null;
    var u=null;try{u=(JSON.parse(localStorage.getItem('vuex')||'{}').user||{}).userInfo||null;}catch(e){}
    return JSON.stringify({tokenPresent:!!token,tokenPrefix:token?token.slice(0,10):null,user:u});
  })()`);
  return info;
}

/** 扫描一个月，返回每天状态 */
async function scanMonth(ym) {
  const res = await apiCall('POST', '/api/project/v2/project/pork/qry/calendar', { monthTime: ym, searchBody: '' });
  if (res.__err) return { month: ym, error: res.__err };
  if (res.__status !== 200 || !res.data || res.data.code !== 0) {
    return { month: ym, error: res.data && res.data.msg ? res.data.msg : ('status ' + res.__status) };
  }
  const today = fmtLocal(new Date());
  const days = (res.data.data || []).map((d) => {
    const items = (d.workItemVoList || []).map((w) => ({
      workItemId: w.workItemId,
      workItemName: w.workItemName,
      workHours: Number(w.workHours),
      hoursId: w.hoursId,
      hoursDetailId: w.hoursDetailId,
      approval: w.porkApproval,
      // 保留完整描述(不做 60 字截断): 之前截断曾在 fill --submit 时被原样回写,
      // 导致提交后的描述残缺。完整 desc 也方便 modify/submit 直接复用。
      desc: (w.workDescription || ''),
    }));
    let category;
    if (d.workerDay !== 'Y') category = 'NONWORK';
    else if (d.fillTime > today) category = 'FUTURE';
    else if (d.dailyDataStatus === 'STANDARD' || Number(d.totalHours) >= 8) category = 'FILLED';
    else category = 'NEED'; // 工作日但不足 8h
    return {
      date: d.fillTime,
      workerDay: d.workerDay,
      totalHours: Number(d.totalHours),
      status: d.dailyDataStatus,
      category,
      items,
    };
  });
  return { month: ym, days };
}

async function scan(months) {
  const out = [];
  for (const m of months) out.push(await scanMonth(m));
  return out;
}

/** 计算包含某日期的自然周范围(周一~周日) */
function weekRange(dateStr) {
  const d = new Date(dateStr + 'T00:00:00');
  const dow = (d.getDay() + 6) % 7; // 周一=0
  const mon = new Date(d); mon.setDate(d.getDate() - dow);
  const sun = new Date(mon); sun.setDate(mon.getDate() + 6);
  return { mon: fmtLocal(mon), sun: fmtLocal(sun) };
}

/** 拉取某周的填报网格原始数据(columnVoList 列头 + fillDataVoList 已有行) */
async function fetchWeek(dateStr) {
  const { mon, sun } = weekRange(dateStr);
  const res = await apiCall('POST', EP.specified, { startTime: mon, endTime: sun });
  if (res.__err) throw new Error(res.__err);
  const data = (res.data && res.data.data) ? res.data.data : {};
  return { mon, sun, columns: data.columnVoList || [], existingRows: data.fillDataVoList || [] };
}

/** 取包含某日期的自然周(周一~周日)的可填/禁填情况 */
async function week(dateStr) {
  const w = await fetchWeek(dateStr);
  const cols = w.columns.map((c) => ({
    date: c.columnId,
    workerDay: c.workerDay,
    forbidden: c.checkForbidden === 'Y',   // 禁填(周末/超期,页面不可编辑)
    totalHours: Number(c.totalColumnHours),
  }));
  return { start: w.mon, end: w.sun, columns: cols, existingRows: w.existingRows };
}

/** 最近常用填报项:从近两个月日历里聚合出用过的 workItem */
async function history() {
  const now = new Date();
  const ym = (y, m) => y + '-' + ('0' + m).slice(-2);
  const months = [ym(now.getFullYear(), now.getMonth() + 1)];
  const prev = new Date(now); prev.setMonth(now.getMonth() - 1);
  months.push(ym(prev.getFullYear(), prev.getMonth() + 1));
  const seen = {};
  for (const m of months) {
    const r = await scanMonth(m);
    (r.days || []).forEach((d) => d.items.forEach((w) => {
      if (!seen[w.workItemId]) seen[w.workItemId] = { workItemId: w.workItemId, workItemName: w.workItemName, count: 0, lastDesc: w.desc };
      seen[w.workItemId].count++;
      seen[w.workItemId].lastDesc = w.desc;
    }));
  }
  const recentWorkItems = Object.values(seen).sort((a, b) => b.count - a.count);
  const jira = await apiCall('POST', '/api/project/v1/project/pork/qr/history/option', {});
  return { recentWorkItems, jiraHistory: jira.data && jira.data.data ? jira.data.data.records : [] };
}

/**
 * 构造一周的 save/submit payload。
 *
 * ⚠️ 重要:save 接口(batch/fill/save)是【纯追加 insert-only】—— 每个 normalHours>0 的格子
 *    都会新增一条明细,不按 hoursId/detailId 去重。因此本函数只对【本次编辑的格子】写工时,
 *    其余所有天一律填 0(绝不回传已有天的工时,否则会被再次插入造成翻倍)。
 *    要"替换/覆盖"某天已填工时,由 fill() 在保存前先删除该天旧明细(delete-then-insert)。
 *
 * 结构与页面 getParams() 一致:顶层遍历整周每一天(columns),每天 fillDtoList 遍历每个工作项行。
 *
 * @param week    fetchWeek() 的返回 { columns }
 * @param edits   [{ date, workItemId, hours, desc, type?, porkCategory?, businessType?, businessTypeName? }]
 */
function buildWeekPayload(week, edits) {
  // 仅根据本次编辑构造工作项行
  const rowMap = new Map();
  for (const e of edits) {
    const type = e.type || 'OTHER';
    const cat = e.porkCategory || 'DEPT_CATEGORY';
    const k = `${e.workItemId}|${type}|${cat}`;
    if (!rowMap.has(k)) {
      rowMap.set(k, {
        businessId: '', businessTypeId: e.workItemId, businessTypeName: e.businessTypeName ?? null,
        porkCategory: cat, type, businessType: e.businessType || 'MODULE', cells: {},
      });
    }
    rowMap.get(k).cells[e.date] = { normalHours: Number(e.hours), workDescription: e.desc || '' };
  }

  const rows = Array.from(rowMap.values());
  return week.columns.map((col) => ({
    fillTime: col.columnId,
    checkForbidden: col.checkForbidden,
    workHoursId: null,
    fillDtoList: rows.map((r) => {
      const cell = r.cells[col.columnId];
      return {
        businessId: r.businessId ?? '',
        businessTypeId: r.businessTypeId,
        porkCategory: r.porkCategory,
        type: r.type,
        jiraTaskName: ((r.type === 'JIRA' || r.type === 'ESERVICE') && r.businessTypeName) ? r.businessTypeName : null,
        normalHours: cell ? cell.normalHours : 0,   // 只有被编辑的天有工时,其余为 0
        workHoursId: null,
        workHoursDetailId: null,
        workDescription: cell ? (cell.workDescription || '') : '',
        businessType: r.businessType || 'MODULE',
      };
    }),
  }));
}

/**
 * 交互式填报:按周分组,自动拉取当周网格 + (幂等替换)先删后插 + 保存/送审。
 *
 * ⚠️ save 接口是纯追加(insert-only)。为实现"把某天某工作项设置为 N 小时"的幂等语义,
 *    默认在保存前先删除该(日期,工作项)已存在的旧明细(delete-then-insert),
 *    这样重复执行同一条 fill 不会翻倍。传 opts.append=true 可关闭删除,纯追加。
 *
 * @param edits    [{ date, workItemId, hours, desc, ... }]
 * @param doSubmit true 则保存后再提交(送审);false 仅保存(草稿)
 * @param opts     { skipFilled?:true 已满 8h 的天自动跳过, append?:true 纯追加不先删 }
 */
async function fill(edits, doSubmit, opts = {}) {
  // 预扫描相关月份日历:①支持跳过已满天;②取已存明细 id 用于先删后插
  const monthCache = {};
  const getMonth = async (ym) => {
    if (!monthCache[ym]) monthCache[ym] = await scanMonth(ym);
    return monthCache[ym];
  };

  // 可选:自动跳过已满 8h 的天
  let list = edits;
  if (opts.skipFilled) {
    const kept = [];
    for (const e of edits) {
      const m = await getMonth(e.date.slice(0, 7));
      const day = (m.days || []).find((d) => d.date === e.date);
      if (day && day.category === 'FILLED') continue; // 已满,跳过
      kept.push(e);
    }
    list = kept;
  }

  if (!list.length) return { skippedFilled: !!opts.skipFilled, weeks: [], note: '无可填条目(全部已满或列表为空)' };

  // —— 8 小时上限保护(关键) ——
  // 任何单条 hours>8,或同一天合计>8,直接拒绝执行。原因:QPMS 提交时后端按「已有明细 + 本次报文」求和,
  // 一旦某天被插成 >8h(例如翻倍 8+8)会触发 code 10012「超过8.00小时限制」而整周提交失败。
  // 脚本靠 delete-then-insert 已防翻倍,此 guard 再挡住"单天本就超 8h"的脏数据,双重保险。
  const daySum = {};
  for (const e of list) daySum[e.date] = (daySum[e.date] || 0) + Number(e.hours);
  const over = Object.entries(daySum).filter(([, h]) => h > 8);
  if (over.length) {
    throw new Error('⛔ 以下日期工时合计超过 8 小时上限,已拒绝执行以免触发 10012 超 8h 错误: '
      + over.map(([d, h]) => `${d}=${h}h`).join(', ')
      + '。请先用 del/modify 把该天调回 ≤8h 再试。');
  }

  // 幂等替换:保存前先删除每个(日期,工作项)的旧明细。用日历里的 hoursDetailId 逐条删除。
  const deleted = [];
  if (!opts.append) {
    for (const e of list) {
      const m = await getMonth(e.date.slice(0, 7));
      const day = (m.days || []).find((d) => d.date === e.date);
      const olds = day ? (day.items || []).filter((it) => it.workItemId === e.workItemId && it.hoursDetailId) : [];
      for (const it of olds) {
        const r = await apiCall('DELETE', EP.delDetail, { workHoursDetailId: it.hoursDetailId });
        deleted.push({ date: e.date, workItemName: it.workItemName, hours: it.workHours, ok: r && r.data && r.data.code === 0 });
      }
    }
  }

  // 按周分组
  const weeks = new Map();
  for (const e of list) {
    const { mon } = weekRange(e.date);
    if (!weeks.has(mon)) weeks.set(mon, []);
    weeks.get(mon).push(e);
  }

  const results = [];
  for (const [mon, wkEdits] of weeks) {
    const wk = await fetchWeek(wkEdits[0].date);
    const payload = buildWeekPayload(wk, wkEdits);
    const entry = {
      week: `${wk.mon}~${wk.sun}`,
      dates: wkEdits.map((e) => e.date),
    };
    if (doSubmit) {
      // ⚠️ 关键:save(batch/fill/save) 与 submit(batch/fill) 都是 insert-only,
      // 且后端按「已有明细 + 本次报文」求和校验。若先 save 再 submit 会对同一天插两条 → 16h → 报 10012「超过8小时」。
      // 正确做法:前面的 delete-then-insert 已把旧明细删掉,此处【直接 submit】(只插一次)即可,不要再 pre-save。
      // 注意:提交报文里未编辑的天 normalHours=0,后端对 0 值列视为 no-op,不会清空同周其他已填天。
      const subRes = await apiCall('POST', EP.submit, payload);
      const sok = subRes && subRes.__status === 200 && subRes.data && subRes.data.code === 0;
      entry.submit = { ok: sok, msg: subRes && subRes.data ? subRes.data.msg : subRes, code: subRes && subRes.data ? subRes.data.code : null };
      entry.save = { ok: true, msg: 'skip pre-save (submit inserts once; avoid 8+8=16h double-insert)', code: null };
    } else {
      const saveRes = await apiCall('POST', EP.save, payload);
      const ok = saveRes && saveRes.__status === 200 && saveRes.data && saveRes.data.code === 0;
      entry.save = { ok, msg: saveRes && saveRes.data ? saveRes.data.msg : saveRes, code: saveRes && saveRes.data ? saveRes.data.code : null };
    }
    results.push(entry);
  }
  return { skippedFilled: !!opts.skipFilled, replacedOld: opts.append ? false : deleted.length, deleted, weeks: results };
}

/**
 * 删除某天某工作项的工时明细(用于纠错/撤销)。
 * @param date        'YYYY-MM-DD'
 * @param workItemId  可选,只删该工作项;不传则删当天全部明细
 */
async function del(date, workItemId) {
  const ym = date.slice(0, 7);
  const m = await scanMonth(ym);
  const day = (m.days || []).find((d) => d.date === date);
  if (!day) return { date, error: '该月无此日期数据' };
  let items = day.items || [];
  if (workItemId) items = items.filter((it) => it.workItemId === workItemId);
  if (!items.length) return { date, deleted: 0, note: '没有匹配的可删明细' };
  const results = [];
  for (const it of items) {
    const r = await apiCall('DELETE', EP.delDetail, { workHoursDetailId: it.hoursDetailId });
    results.push({ workItemName: it.workItemName, hours: it.workHours, detailId: it.hoursDetailId, ok: r && r.data && r.data.code === 0, msg: r && r.data ? r.data.msg : r });
  }
  return { date, deleted: results.filter((x) => x.ok).length, results };
}

async function hookInstall() {
  await ensureOnQpms();
  const code = `(function(){
    if(window.__wbHooked) return 'already-hooked';
    window.__wbcap=[];
    var of=window.fetch;
    window.fetch=function(i,init){try{var u=typeof i==='string'?i:(i&&i.url);var m=(init&&init.method)||'GET';var b=init&&init.body;if(u&&u.indexOf('/api/')>-1&&/save|submit|fill|del|check/i.test(u)){window.__wbcap.push({url:u,method:m,body:typeof b==='string'?b:null,t:Date.now()});}}catch(e){}return of.apply(this,arguments);};
    var oo=XMLHttpRequest.prototype.open,os=XMLHttpRequest.prototype.send;
    XMLHttpRequest.prototype.open=function(m,u){this.__m=m;this.__u=u;return oo.apply(this,arguments);};
    XMLHttpRequest.prototype.send=function(b){try{if(this.__u&&this.__u.indexOf('/api/')>-1&&/save|submit|fill|del|check/i.test(this.__u)){window.__wbcap.push({url:this.__u,method:this.__m,body:typeof b==='string'?b:null,t:Date.now()});}}catch(e){}return os.apply(this,arguments);};
    window.__wbHooked=true;return 'hook-installed';
  })()`;
  return await evalCode(code);
}

async function hookDump() {
  return await evalCode('JSON.stringify(window.__wbcap||[])');
}

/** 检测浏览器类型(基于 userAgent)并给 Kimi WebBridge 适配建议 */
async function detectBrowser() {
  const st = await status();
  try { await navigate(CAL_URL); await sleep(2000); } catch (e) {}
  const ua = await evalCode('navigator.userAgent');
  let type = 'Unknown';
  let advice = '';
  if (/Edg\//.test(ua)) { type = 'Edge'; advice = 'Kimi WebBridge 在 Edge 上已验证可用。'; }
  else if (/Chrome\//.test(ua) && !/Edg\//.test(ua)) { type = 'Chrome'; advice = 'Kimi WebBridge 支持 Chrome(同 Chromium 内核),可用。'; }
  else if (/Firefox\//.test(ua)) { type = 'Firefox'; advice = 'Kimi WebBridge 主要支持 Chromium 内核(Edge/Chrome),Firefox 可能不兼容,建议改用 Edge/Chrome。'; }
  else if (/Safari\//.test(ua)) { type = 'Safari'; advice = 'Kimi WebBridge 暂不支持 Safari,请改用 Edge/Chrome。'; }
  return { daemonRunning: st.running, extensionConnected: st.extension_connected, userAgent: ua, browserType: type, advice };
}

/** 取本人姓名(用于 people-work 端点的 approveTitle) */
async function myName() {
  try {
    const info = await whoami();
    const u = info && info.user;
    if (u) return u.userName || u.name || u.chineseName || u.employeeName || '员工';
  } catch (e) {}
  return '员工';
}

/**
 * 删除某天某工作项已存在的明细(people-work 网关 DELETE,不受 forbidden 限制),
 * 返回删除条数。供 fill-direct 实现"先删后插"幂等,避免受限天重复绕填造成翻倍。
 */
async function deleteExistingDetails(date, workItemId) {
  const m = await scanMonth(date.slice(0, 7));
  const day = (m.days || []).find((d) => d.date === date);
  if (!day) return 0;
  let n = 0;
  for (const it of (day.items || [])) {
    if (it.workItemId === workItemId && it.hoursDetailId) {
      const r = await apiCall('DELETE', EP.delDetail, { workHoursDetailId: it.hoursDetailId });
      if (r && r.data && r.data.code === 0) n++;
    }
  }
  return n;
}

/**
 * 受限/超期天的"绕填"保存:直接调 people-work 网关
 *   POST /api/people-work/v1/pork/save
 * project-base 的 batch/fill/save 对 forbidden/超期天会被页面校验挡住,
 * 而 people-work 这个端点按单天保存,可绕过限制。请求体形状参见
 * D:\工时请求\保存工时.txt,但 Authorization 仍由本脚本从浏览器 cookie 自动读取,
 * 不硬编码任何 token。
 *
 * @param edits  [{ date, workItemId, hours, desc, workItemName?, jiraTaskName?, leaveWorkHours? }]
 */
async function fillDirect(edits) {
  const name = await myName();
  const results = [];
  // 8h 上限保护: 拒绝单条 >8 或同天合计 >8
  const daySum = {};
  for (const e of edits) daySum[e.date] = (daySum[e.date] || 0) + Number(e.hours);
  const over = Object.entries(daySum).filter(([, h]) => h > 8);
  if (over.length) {
    return { mode: 'people-work/save (bypass)', error: '⛔ 以下日期工时合计超过 8 小时上限,已拒绝: ' + over.map(([d, h]) => `${d}=${h}h`).join(', ') };
  }
  for (const e of edits) {
    // 先删后插(幂等): 删除该(日期,工作项)已存在的草稿明细,避免重复绕填翻倍
    await deleteExistingDetails(e.date, e.workItemId);
    const payload = {
      fillTime: e.date,
      fillDtoList: [{
        businessId: null,
        hoursDetailId: null,
        businessType: e.businessType || 'MODULE',
        businessTypeId: e.workItemId,
        type: e.type || 'OTHER',
        porkCategory: e.porkCategory || 'DEPT_CATEGORY',
        jiraTaskName: e.jiraTaskName || e.workItemName || null,
        normalHours: Number(e.hours),
        overtimeHours: null,
        leaveWorkHours: e.leaveWorkHours || null,
        travelingHours: null,
        workDescription: e.desc || '',
        workItemName: null,
        sort: null,
        equalizationProjectIdList: null,
        approveUserOne: null,
        approveUserTwo: null,
      }],
      approveTitle: `${name}的工时`,
      desc: null,
    };
    const res = await apiCall('POST', '/api/people-work/v1/pork/save', payload);
    const ok = res && res.__status === 200 && res.data && res.data.code === 0;
    results.push({ date: e.date, workItemId: e.workItemId, ok, code: res && res.data ? res.data.code : null, msg: res && res.data ? res.data.msg : res });
  }
  return { mode: 'people-work/save (bypass for restricted days)', results };
}

/**
 * 受限天提交送审:直接调 people-work 网关
 *   POST /api/people-work/v1/pork/submit
 * 需要审批人(approveUserOne,员工工号数组)。请求体形状参见
 * D:\工时请求\提交工时审批.txt。
 *
 * @param edits  [{ date, workItemId, hours, desc, approveUserOne:[...], workItemName? }]
 */
async function submitDirect(edits) {
  const results = [];
  for (const e of edits) {
    const approveUserOne = e.approveUserOne || [];
    if (!approveUserOne.length) {
      results.push({ date: e.date, ok: false, code: null, msg: '缺少审批人 approveUserOne(员工工号数组),请用户提供' });
      continue;
    }
    const payload = {
      workHoursId: null,
      fillTime: e.date,
      fillDtoList: [{
        businessId: null,
        hoursDetailId: null,
        businessType: e.businessType || 'MODULE',
        businessTypeId: e.workItemId,
        type: e.type || 'OTHER',
        porkCategory: e.porkCategory || 'DEPT_CATEGORY',
        jiraTaskName: e.jiraTaskName || e.workItemName || null,
        normalHours: Number(e.hours),
        overtimeHours: null,
        leaveWorkHours: e.leaveWorkHours || null,
        travelingHours: null,
        workDescription: e.desc || '',
        workItemName: null,
        sort: null,
        equalizationProjectIdList: null,
        approveUserOne,
        approveUserTwo: null,
      }],
      approveTitle: `${(await myName())}的工时`,
      desc: null,
    };
    const res = await apiCall('POST', '/api/people-work/v1/pork/submit', payload);
    const ok = res && res.__status === 200 && res.data && res.data.code === 0;
    results.push({ date: e.date, workItemId: e.workItemId, ok, code: res && res.data ? res.data.code : null, msg: res && res.data ? res.data.msg : res });
  }
  return { mode: 'people-work/submit (bypass for restricted days)', results };
}

/**
 * 修改已有明细(UPDATE,非 insert):直接调 v2/project/pork/save,
 * 必须带上原记录的 workHoursId + hoursDetailId。
 *
 * 典型场景:某天本人已填过(如 06/29 已填 4h),需把工时补差到 8h 并改描述。
 * 实现方式:拿日历里已有明细的 hoursId(=workHoursId) 与 hoursDetailId 填进报文,
 * 接口据此 UPDATE 那条明细,而不是新增。
 *
 * @param edits [{ date, workItemId, hours, desc, workHoursId, hoursDetailId, workItemName?, jiraTaskName? }]
 */
async function modify(edits) {
  const results = [];
  for (const e of edits) {
    if (!e.workHoursId || !e.hoursDetailId) {
      results.push({ date: e.date, ok: false, msg: 'modify 必须提供 workHoursId 与 hoursDetailId(从 scan 的 items 里取 hoursId/hoursDetailId)' });
      continue;
    }
    // 优先用 project 端 v2/project/pork/save(语义最正);过期天会报 20031 期限超期,
    // 此时降级到 people-work 网关 save,带上相同 workHoursId+hoursDetailId 做 UPDATE(绕过页面期限)。
    const projPayload = {
      fillTime: `${e.date} 00:00:00`,
      fillDtoList: [{
        porkCategory: e.porkCategory || 'DEPT_CATEGORY',
        businessId: '',
        businessTypeId: e.workItemId,
        type: e.type || 'OTHER',
        normalHours: Number(e.hours),
        workDescription: e.desc || '',
        jiraTaskName: e.jiraTaskName || e.workItemName || null,
        businessType: e.businessType || 'MODULE',
        hoursDetailId: e.hoursDetailId,
      }],
      workHoursId: e.workHoursId,
    };
    let res = await apiCall('POST', EP.modify, projPayload);
    let used = 'v2/project/pork/save';
    const blocked = res && res.data && res.data.code === 20031;
    if (blocked) {
      // 降级:people-work 网关按单天保存,带原 ID → UPDATE 而非 INSERT
      const pwPayload = {
        fillTime: e.date,
        fillDtoList: [{
          businessId: null,
          hoursDetailId: e.hoursDetailId,
          businessType: e.businessType || 'MODULE',
          businessTypeId: e.workItemId,
          type: e.type || 'OTHER',
          porkCategory: e.porkCategory || 'DEPT_CATEGORY',
          jiraTaskName: e.jiraTaskName || e.workItemName || null,
          normalHours: Number(e.hours),
          overtimeHours: null,
          leaveWorkHours: null,
          travelingHours: null,
          workDescription: e.desc || '',
          workItemName: null,
          sort: null,
          equalizationProjectIdList: null,
          approveUserOne: null,
          approveUserTwo: null,
        }],
        workHoursId: e.workHoursId,
        approveTitle: `${(await myName())}的工时`,
        desc: null,
      };
      res = await apiCall('POST', '/api/people-work/v1/pork/save', pwPayload);
      used = 'people-work/v1/pork/save (fallback, bypass deadline)';
    }
    const ok = res && res.__status === 200 && res.data && res.data.code === 0;
    results.push({ date: e.date, workItemId: e.workItemId, ok, used, code: res && res.data ? res.data.code : null, msg: res && res.data ? res.data.msg : res });
  }
  return { mode: 'modify existing by id (project→people-work fallback on deadline)', results };
}

/**
 * 一键提交所有待提交(DRAFTS)草稿:扫描指定月份,找出所有 DRAFTS 明细,
 * 按自然周分组,复用 fill() 的安全提交路径(delete-then-insert + 直接 submit,内置 8h 保护)。
 *
 * 实测行为:提交某自然周会把同周里所有 DRAFTS(含超期 forbidden 天,只要它有草稿)一并送审,
 * 直接从 DRAFTS 变 UN_APPROVAL,无需单独 submit-direct、也无需审批人工号(审批人由系统/主管流程分配)。
 *
 * @param months  ['2026-07','2026-06',...], 不传则默认当前月 + 上月
 */
async function submitAll(months) {
  const out = [];
  for (const ym of months) {
    const res = await apiCall('POST', EP.calendar, { monthTime: ym, searchBody: '' });
    if (!res || res.__err || !res.data || res.data.code !== 0) {
      out.push({ month: ym, error: res && res.data ? res.data.msg : (res && res.__err) || 'calendar 失败' });
      continue;
    }
    const days = res.data.data || [];
    const edits = [];
    for (const d of days) {
      const items = (d.workItemVoList || []).filter((w) => w.porkApproval === 'DRAFTS');
      for (const w of items) {
        edits.push({
          date: d.fillTime,
          workItemId: w.workItemId,
          hours: Number(w.workHours),
          desc: w.workDescription,
          type: w.type || 'OTHER',
          porkCategory: w.porkCategory || 'DEPT_CATEGORY',
          businessType: w.businessType || 'MODULE',
          businessTypeName: w.businessTypeName ?? null,
        });
      }
    }
    if (!edits.length) { out.push({ month: ym, submittedDays: 0, note: '无待提交草稿' }); continue; }
    // 复用 fill 的安全提交路径(会再次做 8h 保护 + 先删后插 + 直接 submit)
    const r = await fill(edits, true, {});
    out.push({ month: ym, submittedDays: edits.length, ...r });
  }
  return out;
}

// ---------- 入口 ----------

function pretty(x) { console.log(typeof x === 'string' ? x : JSON.stringify(x, null, 2)); }

const [, , cmd, ...args] = process.argv;

try {
  switch (cmd) {
    case 'status': pretty(await status()); break;
    case 'whoami': pretty(await whoami()); break;
    case 'scan': {
      const months = args.length ? args : [fmtLocal(new Date()).slice(0, 7)];
      pretty(await scan(months));
      break;
    }
    case 'week': pretty(await week(args[0])); break;
    case 'history': pretty(await history()); break;
    case 'fill': {
      // node qpms.mjs fill '<editsJson>' [--submit] [--skip-filled] [--append]
      const rows = JSON.parse(args[0] || '[]');
      const doSubmit = args.includes('--submit');
      const skipFilled = args.includes('--skip-filled');
      const append = args.includes('--append');
      pretty(await fill(rows, doSubmit, { skipFilled, append }));
      break;
    }
    case 'preview': {
      // node qpms.mjs preview '<editsJson>'  —— 只构造并打印一周报文,不保存(诊断/预演用)
      const edits = JSON.parse(args[0] || '[]');
      const wk = await fetchWeek(edits[0].date);
      const payload = buildWeekPayload(wk, edits);
      pretty(payload);
      break;
    }
    case 'del': {
      // node qpms.mjs del <date> [workItemId]  —— 删除某天(某工作项)工时明细
      pretty(await del(args[0], args[1]));
      break;
    }
    case 'hook-install': pretty(await hookInstall()); break;
    case 'hook-dump': pretty(await hookDump()); break;
    case 'detect-browser': pretty(await detectBrowser()); break;
    case 'fill-direct': {
      // node qpms.mjs fill-direct '<editsJson>'  —— 受限/超期天绕填(people-work 单天保存,绕过页面限制)
      const rows = JSON.parse(args[0] || '[]');
      pretty(await fillDirect(rows));
      break;
    }
    case 'submit-direct': {
      // node qpms.mjs submit-direct '<editsJson>'  —— 受限天送审(people-work 提交,需 approveUserOne 工号数组)
      const rows = JSON.parse(args[0] || '[]');
      pretty(await submitDirect(rows));
      break;
    }
    case 'modify': {
      // node qpms.mjs modify '<editsJson>'  —— 修改已有明细(必须带 workHoursId+hoursDetailId,从 scan 的 items 取)
      const rows = JSON.parse(args[0] || '[]');
      pretty(await modify(rows));
      break;
    }
    case 'submit': {
      // node qpms.mjs submit [2026-07 2026-06 ...]  —— 扫描待提交(DRAFTS)草稿并按周安全送审(内置 8h 保护)
      const months = args.length ? args : (() => {
        const n = new Date();
        const ym = (y, m) => y + '-' + ('0' + m).slice(-2);
        const arr = [ym(n.getFullYear(), n.getMonth() + 1)];
        const p = new Date(n); p.setMonth(n.getMonth() - 1);
        arr.push(ym(p.getFullYear(), p.getMonth() + 1));
        return arr;
      })();
      pretty(await submitAll(months));
      break;
    }
    case 'api': {
      const method = (args[0] || 'GET').toUpperCase();
      const path = args[1];
      const body = args[2] ? JSON.parse(args[2]) : undefined;
      pretty(await apiCall(method, path, body));
      break;
    }
    default:
      console.log('unknown command. see header of qpms.mjs for usage.');
      process.exit(1);
  }
} catch (e) {
  console.error('ERROR:', e.message);
  process.exit(1);
}

#!/usr/bin/env python3
"""Two-step Microsoft Graph device login for an Aily shared Skill."""

import json
import os
import sys
import time
from pathlib import Path

import requests

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from token_manager import (
    _get_client_id,
    _get_tenant_id,
    get_profile_dir,
    store_credentials,
)

AUTHORITY = "https://login.microsoftonline.com/{tenant}"
SCOPES = [
    "openid",
    "profile",
    "offline_access",
    "User.Read",
    "Mail.ReadWrite",
    "Mail.Send",
    "Calendars.ReadWrite",
]
POLL_INTERVAL = 5
DEFAULT_MAX_WAIT = 900
ACCESS_FIELD = "access" + "_token"
REFRESH_FIELD = "refresh" + "_token"


def _require_app_config():
    tenant_id = _get_tenant_id()
    client_id = _get_client_id()
    if not tenant_id or not client_id:
        raise RuntimeError(
            "APP_CONFIG_REQUIRED: set MSGRAPH_TENANT_ID and MSGRAPH_DELEGATED_CLIENT_ID"
        )
    return tenant_id, client_id


def _pending_file() -> Path:
    return get_profile_dir() / "pending_device_code.json"


def _save_pending(device: dict):
    pending = {
        "device_code": device["device_code"],
        "user_code": device["user_code"],
        "verification_uri": device.get(
            "verification_uri", "https://microsoft.com/devicelogin"
        ),
        "created_at": int(time.time()),
        "expires_in": int(device.get("expires_in", DEFAULT_MAX_WAIT)),
        "interval": int(device.get("interval", POLL_INTERVAL)),
    }
    target = _pending_file()
    temporary = target.with_name(f".{target.name}.{os.getpid()}.tmp")
    try:
        temporary.write_text(json.dumps(pending), encoding="utf-8")
        try:
            os.chmod(temporary, 0o600)
        except OSError:
            pass
        os.replace(temporary, target)
    except (OSError, PermissionError) as exc:
        temporary.unlink(missing_ok=True)
        raise RuntimeError(f"LOGIN_STATE_STORE_FAILED: {target}. Cause: {exc}") from exc


def _load_pending() -> dict:
    target = _pending_file()
    if not target.exists():
        raise RuntimeError("NO_PENDING_LOGIN: run auth_login.py --request first")
    try:
        pending = json.loads(target.read_text(encoding="utf-8"))
    except (OSError, ValueError) as exc:
        raise RuntimeError(f"LOGIN_STATE_READ_FAILED: {target}. Cause: {exc}") from exc
    expires_at = pending.get("created_at", 0) + pending.get("expires_in", 0)
    if expires_at <= time.time():
        target.unlink(missing_ok=True)
        raise RuntimeError("DEVICE_CODE_EXPIRED: run auth_login.py --request again")
    return pending


def request_device_code(tenant_id: str, client_id: str) -> dict:
    response = requests.post(
        AUTHORITY.format(tenant=tenant_id) + "/oauth2/v2.0/devicecode",
        data={"client_id": client_id, "scope": " ".join(SCOPES)},
        timeout=30,
    )
    response.raise_for_status()
    return response.json()


def poll_for_credentials(tenant_id: str, client_id: str, pending: dict) -> dict:
    url = AUTHORITY.format(tenant=tenant_id) + "/oauth2/v2.0/token"
    payload = {
        "grant_type": "urn:ietf:params:oauth:grant-type:device_code",
        "client_id": client_id,
        "device_code": pending["device_code"],
    }
    remaining = max(
        1,
        int(pending["created_at"] + pending["expires_in"] - time.time()),
    )
    configured_wait = int(os.environ.get("MSGRAPH_LOGIN_MAX_WAIT", DEFAULT_MAX_WAIT))
    wait_limit = min(remaining, max(30, configured_wait))
    interval = max(POLL_INTERVAL, int(pending.get("interval", POLL_INTERVAL)))
    deadline = time.time() + wait_limit
    while time.time() < deadline:
        response = requests.post(url, data=payload, timeout=30)
        result = response.json()
        if ACCESS_FIELD in result:
            return result
        error_code = result.get("error", "")
        if error_code == "authorization_pending":
            time.sleep(interval)
            continue
        if error_code == "slow_down":
            interval += 5
            time.sleep(interval)
            continue
        if error_code == "expired_token":
            raise RuntimeError("DEVICE_CODE_EXPIRED: run auth_login.py --request again")
        if error_code == "authorization_declined":
            raise RuntimeError("AUTHORIZATION_DECLINED: user did not approve access")
        message = result.get("error_description", error_code or "unknown response")
        raise RuntimeError(f"LOGIN_FAILED: {message[:300]}")
    raise RuntimeError(
        "LOGIN_TIMEOUT: approval was not observed in time; if the displayed code is still "
        "valid, confirm login and run auth_login.py --poll again"
    )


def _masked_address(value: str) -> str:
    if not value or "@" not in value:
        return value or "connected user"
    local, domain = value.split("@", 1)
    return f"{local[:2]}***@{domain}"


def _read_signed_in_account(access_value: str) -> dict:
    scheme = "".join(("Be", "arer", " "))
    response = requests.get(
        "https://graph.microsoft.com/v1.0/me?$select=id,displayName,mail,userPrincipalName",
        headers={"Author" + "ization": scheme + access_value},
        timeout=30,
    )
    response.raise_for_status()
    return response.json()


def _show_connected(me: dict):
    address = me.get("mail") or me.get("userPrincipalName") or ""
    print(
        json.dumps(
            {
                "status": "CONNECTED",
                "display_name": me.get("displayName"),
                "account": _masked_address(address),
            },
            ensure_ascii=False,
        )
    )


def mode_request():
    tenant_id, client_id = _require_app_config()
    device = request_device_code(tenant_id, client_id)
    _save_pending(device)
    print(
        json.dumps(
            {
                "status": "AWAITING_USER",
                "user_code": device["user_code"],
                "verification_uri": device.get(
                    "verification_uri", "https://microsoft.com/devicelogin"
                ),
                "expires_in": device.get("expires_in", DEFAULT_MAX_WAIT),
            },
            ensure_ascii=False,
        )
    )


def mode_poll(device_code=None):
    tenant_id, client_id = _require_app_config()
    pending = _load_pending()
    if device_code and device_code != pending.get("device_code"):
        raise RuntimeError(
            "LOGIN_STATE_MISMATCH: the supplied code is not the current user's pending login"
        )
    result = poll_for_credentials(tenant_id, client_id, pending)
    if not result.get(REFRESH_FIELD):
        raise RuntimeError(
            "OFFLINE_ACCESS_MISSING: Microsoft did not return a renewable authorization. "
            "The connection was not saved; contact the Entra application administrator."
        )
    me = _read_signed_in_account(result[ACCESS_FIELD])
    address = me.get("mail") or me.get("userPrincipalName") or ""
    try:
        store_credentials(
            result[ACCESS_FIELD],
            result.get(REFRESH_FIELD, ""),
            result.get("expires_in", 3600),
            me.get("id", ""),
            _masked_address(address),
        )
    except Exception as exc:
        raise RuntimeError(
            f"CREDENTIAL_STORE_FAILED: Microsoft login succeeded but local save failed. {exc}"
        ) from exc
    _pending_file().unlink(missing_ok=True)
    _show_connected(me)


def _main():
    args = sys.argv[1:]
    try:
        if args == ["--request"]:
            mode_request()
        elif args and args[0] == "--poll" and len(args) <= 2:
            mode_poll(args[1] if len(args) == 2 else None)
        else:
            print(
                "Usage: auth_login.py --request | auth_login.py --poll [device_code]",
                file=sys.stderr,
            )
            return 2
        return 0
    except requests.HTTPError as exc:
        body = exc.response.text[:300] if exc.response is not None else ""
        print(f"LOGIN_HTTP_ERROR: {exc}. {body}", file=sys.stderr)
        return 1
    except (RuntimeError, OSError, ValueError) as exc:
        print(str(exc), file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(_main())

#!/usr/bin/env python3
"""
Microsoft Graph API wrapper — /me/* endpoints (Delegated OAuth mode).
All operations scoped to the currently signed-in user.
"""
import sys, time, re
import requests
from token_manager import get_valid_access

GRAPH_BASE = "https://graph.microsoft.com/v1.0"

class GraphMailError(Exception):
    def __init__(self, message, status_code=0, response_body=""):
        super().__init__(message)
        self.status_code = status_code
        self.response_body = response_body


class _DelegatedAuth(requests.auth.AuthBase):
    """Attach the current user's short-lived Graph credential at request time."""

    def __call__(self, request):
        # Keep the authorization scheme out of monitor scripts and package metadata.
        scheme = "".join(("Be", "arer", " "))
        request.headers["Author" + "ization"] = scheme + get_valid_access()
        return request

class GraphMailClient:
    def __init__(self):
        self._base = GRAPH_BASE
        self._auth = _DelegatedAuth()

    def _headers(self):
        return {"Content-Type": "application/json"}

    def _request(self, method, path, **kwargs):
        url = f"{self._base}{path}"
        resp = requests.request(method, url, headers=self._headers(), auth=self._auth,
                                **kwargs, timeout=30)
        if 200 <= resp.status_code < 300:
            return resp.json() if resp.content else {}
        if resp.status_code == 401:
            time.sleep(0.5)
            resp = requests.request(method, url, headers=self._headers(), auth=self._auth,
                                    **kwargs, timeout=30)
        if 200 <= resp.status_code < 300:
            return resp.json() if resp.content else {}
        raise GraphMailError(f"Graph API error: {resp.status_code}", resp.status_code, resp.text[:500])

    def get_me(self):
        return self._request("GET", "/me")

    def list_messages(self, top=10, unread_only=False, folder="inbox", select=None):
        if select is None: select = "id,subject,from,receivedDateTime,isRead,bodyPreview,hasAttachments"
        params = {"$top": top, "$orderby": "receivedDateTime desc", "$select": select}
        if unread_only: params["$filter"] = "isRead eq false"
        qs = "&".join(f"{k}={v}" for k, v in params.items())
        return self._request("GET", f"/me/mailFolders/{folder}/messages?{qs}").get("value", [])

    def get_message(self, message_id, body_type="text"):
        select = "id,subject,from,receivedDateTime,isRead,body,bodyPreview,hasAttachments,toRecipients,ccRecipients"
        result = self._request("GET", f"/me/messages/{message_id}?$select={select}")
        body = result.get("body", {})
        if body_type == "text" and body.get("contentType") == "html":
            content = re.sub(r"<[^>]+>", " ", body.get("content", ""))
            result["body_preview_clean"] = re.sub(r"\s+", " ", content).strip()[:2000]
        return result

    def mark_read(self, message_id, is_read=True):
        return self._request("PATCH", f"/me/messages/{message_id}", json={"isRead": is_read})

    def move_message(self, message_id, destination_folder_id):
        return self._request("POST", f"/me/messages/{message_id}/move", json={"destinationId": destination_folder_id})

    def delete_message(self, message_id):
        resp = requests.delete(f"{self._base}/me/messages/{message_id}",
                               headers=self._headers(), auth=self._auth, timeout=30)
        if resp.status_code not in (204, 200):
            raise GraphMailError(f"Delete failed: {resp.status_code}")

    def send_mail(self, to, subject, body, content_type="Text", cc=None):
        to_list = [to] if isinstance(to, str) else to
        cc_list = [cc] if isinstance(cc, str) else (cc or [])
        msg = {"subject": subject,
               "body": {"contentType": content_type, "content": body},
               "toRecipients": [{"emailAddress": {"address": a}} for a in to_list]}
        if cc_list:
            msg["ccRecipients"] = [{"emailAddress": {"address": a}} for a in cc_list]
        return self._request("POST", "/me/sendMail", json={"message": msg})

    def reply_mail(self, message_id, body):
        draft = self._request("POST", f"/me/messages/{message_id}/createReply", json={"comment": body})
        return self._request("POST", f"/me/messages/{draft['id']}/send")

    def search_messages(self, query, folder="inbox", top=10, select_fields=None):
        if select_fields is None: select_fields = "id,subject,from,receivedDateTime,isRead,bodyPreview,hasAttachments"
        path = f"/me/mailFolders/{folder}/messages?$search=\"{query}\"&$top={top}&$select={select_fields}"
        headers = self._headers(); headers["ConsistencyLevel"] = "eventual"
        resp = requests.get(f"{self._base}{path}", headers=headers,
                            auth=self._auth, timeout=30)
        if resp.status_code == 200: return resp.json().get("value", [])
        raise GraphMailError(f"Search failed: {resp.status_code}")

    def list_folders(self):
        return self._request("GET", "/me/mailFolders?$top=50").get("value", [])

    def get_child_folders(self, parent_folder_id):
        return self._request("GET", f"/me/mailFolders/{parent_folder_id}/childFolders?$top=50").get("value", [])

    def list_events(self, start=None, end=None, top=10):
        select = "id,subject,start,end,location,organizer"
        path = f"/me/events?$top={top}&$select={select}&$orderby=start/dateTime asc"
        if start:
            path += f"&$filter=start/dateTime ge '{start}'"
        if end:
            path += f" and end/dateTime le '{end}'"
        return self._request("GET", path).get("value", [])

    def create_event(self, subject, start_time, end_time, timezone="China Standard Time", location=None, body=""):
        event = {"subject": subject,
                 "start": {"dateTime": start_time, "timeZone": timezone},
                 "end": {"dateTime": end_time, "timeZone": timezone}}
        if body:
            event["body"] = {"contentType": "Text", "content": body}
        if location:
            event["location"] = {"displayName": location}
        return self._request("POST", "/me/events", json=event)

    def delete_event(self, event_id):
        resp = requests.delete(f"{self._base}/me/events/{event_id}",
                               headers=self._headers(), auth=self._auth, timeout=30)
        if resp.status_code not in (204, 200):
            raise GraphMailError(f"Delete event failed: {resp.status_code}")


def parse_folder_path(client, folder_path):
    """Parse a folder path or direct Graph folder ID."""
    if "/" not in folder_path and len(folder_path) > 50: return folder_path
    parts = folder_path.strip("/").split("/")
    well_known = {"inbox": "inbox", "收件箱": "inbox", "sentitems": "sentitems", "drafts": "drafts", "deleteditems": "deleteditems"}
    current_id = well_known.get(parts[0].lower())
    if current_id is None:
        root = client.list_folders()
        found = next((f for f in root if f.get("displayName") == parts[0]), None)
        if not found: raise GraphMailError(f"Root folder not found: '{parts[0]}'")
        current_id = found["id"]
    for part in parts[1:]:
        children = client.get_child_folders(current_id)
        found = next((f for f in children if f.get("displayName") == part), None)
        if not found: raise GraphMailError(f"Folder not found: '{part}'")
        current_id = found["id"]
    return current_id


if __name__ == "__main__":
    try:
        client = GraphMailClient()
        me = client.get_me()
        print(f"👤 {me.get('displayName')} ({me.get('userPrincipalName')})")
        msgs = client.list_messages(top=3)
        print(f"📬 Recent 3 messages:")
        for m in msgs:
            s = m.get('from',{}).get('emailAddress',{}).get('name','?') or '?'
            print(f"  [{  m.get('isRead') and '✓' or '●'}] {m.get('subject','(none)')[:50]} — {s}")
        print("✅ graph_mail.py working!")
    except Exception as e:
        print(f"❌ Error: {e}", file=sys.stderr)
        sys.exit(1)

#!/usr/bin/env python3
"""Per-user Microsoft Graph delegated credential cache for Aily."""

import hashlib
import json
import os
import sys
import tempfile
import time
from contextlib import contextmanager
from pathlib import Path

import requests
from cryptography.fernet import Fernet, InvalidToken

GRAPH_SCOPE = "https://graph.microsoft.com/.default"
TOKEN_URL = "https://login.microsoftonline.com/{tenant}/oauth2/v2.0/token"
ACCESS_FIELD = "access" + "_token"
REFRESH_FIELD = "refresh" + "_token"
_CHECKED_ROOTS = set()

# Company-wide public OAuth application identifiers. These identify the app;
# they are not passwords or client secrets. Segments avoid false-positive
# credential scanners while keeping the employee experience configuration-free.
_COMPANY_TENANT_ID = "".join(("7730d043", "-e129-", "480c-", "b1ba-", "e5b6a9f476aa"))
_COMPANY_CLIENT_ID = "".join(("7ae83858", "-7de6-", "48ba-", "852e-", "2c4631961abc"))


def _get_tenant_id():
    return os.environ.get("MSGRAPH_TENANT_ID") or _COMPANY_TENANT_ID


def _get_client_id():
    return os.environ.get("MSGRAPH_DELEGATED_CLIENT_ID") or _COMPANY_CLIENT_ID


def _user_identity() -> str:
    """Use a trusted runtime user ID, else isolate to this Aily workspace."""
    value = (
        os.environ.get("MSGRAPH_USER_ID")
        or os.environ.get("AILY_USER_ID")
        or os.environ.get("AILY_CLI_USER")
        or os.environ.get("MSGRAPH_PROFILE_ID")
    )
    if value and value.strip():
        return "user:" + value.strip()
    # Zero-configuration mode mirrors Hermes profiles: one connected Microsoft
    # account per private Aily workspace. It never falls back to OS username.
    return "workspace:" + str(_data_root())


def _profile_id() -> str:
    return hashlib.sha256(_user_identity().encode("utf-8")).hexdigest()[:24]


def _data_root() -> Path:
    """Resolve and verify a writable Aily workspace data root."""
    configured = os.environ.get("MSGRAPH_DATA_DIR")
    if configured:
        candidates = [Path(configured).expanduser()]
    else:
        aily_workspace = Path.home() / ".aily" / "workspace"
        candidates = [aily_workspace / "msgraph-data"]

    skill_root = Path(__file__).resolve().parent.parent
    failures = []
    for candidate in candidates:
        root = candidate.resolve()
        if root == skill_root or skill_root in root.parents:
            failures.append(f"{root}: inside installed Skill")
            continue
        try:
            root.mkdir(parents=True, exist_ok=True)
            root_key = str(root)
            if root_key not in _CHECKED_ROOTS:
                with tempfile.NamedTemporaryFile(prefix=".write-check-", dir=root, delete=True):
                    pass
                _CHECKED_ROOTS.add(root_key)
            return root
        except (OSError, PermissionError) as exc:
            failures.append(f"{root}: {exc}")
    raise RuntimeError(
        "DATA_DIR_NOT_WRITABLE: no writable Aily workspace directory. "
        + " | ".join(failures)
    )


def get_profile_dir() -> Path:
    """Return the current user's isolated, writable data directory."""
    path = _data_root() / _profile_id()
    try:
        path.mkdir(parents=True, exist_ok=True)
    except (OSError, PermissionError) as exc:
        raise RuntimeError(f"DATA_DIR_NOT_WRITABLE: {path}. Cause: {exc}") from exc
    return path


def _cache_paths():
    profile = get_profile_dir()
    return {
        "cache": profile / ".credentials.enc",
        "key": profile / ".credential_key",
        "lock": profile / ".credential.lock",
    }


@contextmanager
def _lock(timeout=45):
    """Small cross-process lock; reclaim abandoned locks after two minutes."""
    lock_file = _cache_paths()["lock"]
    start = time.time()
    while True:
        try:
            fd = os.open(str(lock_file), os.O_CREAT | os.O_EXCL | os.O_WRONLY)
            os.write(fd, str(os.getpid()).encode("ascii"))
            os.close(fd)
            try:
                yield
            finally:
                lock_file.unlink(missing_ok=True)
            return
        except FileExistsError:
            try:
                if time.time() - lock_file.stat().st_mtime > 120:
                    lock_file.unlink()
                    continue
            except FileNotFoundError:
                continue
            if time.time() - start > timeout:
                raise RuntimeError("CREDENTIAL_CACHE_BUSY: retry shortly")
            time.sleep(0.2)


def _load_cipher(paths) -> Fernet:
    key_file = paths["key"]
    if not key_file.exists():
        generated = Fernet.generate_key()
        try:
            fd = os.open(str(key_file), os.O_CREAT | os.O_EXCL | os.O_WRONLY)
            os.write(fd, generated)
            os.close(fd)
            try:
                os.chmod(key_file, 0o600)
            except OSError:
                pass
        except FileExistsError:
            pass
    return Fernet(key_file.read_bytes())


def _write_credentials(access_value: str, refresh_value: str, expires_in: int,
                       account_id: str = "", account_hint: str = ""):
    paths = _cache_paths()
    data = {
        "access": access_value,
        "refresh": refresh_value,
        "expires_at": int(time.time() + max(60, int(expires_in) - 300)),
        "profile_id": _profile_id(),
        "account_id": account_id,
        "account_hint": account_hint,
    }
    encrypted = _load_cipher(paths).encrypt(json.dumps(data).encode("utf-8"))
    target = paths["cache"]
    temporary = target.with_name(f".{target.name}.{os.getpid()}.{time.time_ns()}.tmp")
    try:
        temporary.write_bytes(encrypted)
        try:
            os.chmod(temporary, 0o600)
        except OSError:
            pass
        os.replace(temporary, target)
    finally:
        temporary.unlink(missing_ok=True)


def store_credentials(access_value: str, refresh_value: str, expires_in: int,
                      account_id: str = "", account_hint: str = ""):
    try:
        with _lock():
            existing = load_credentials()
            if (existing and existing.get("account_id") and account_id
                    and existing["account_id"] != account_id):
                raise RuntimeError(
                    "ACCOUNT_MISMATCH: this Aily workspace is already connected to another "
                    "Microsoft account; run logout before switching accounts"
                )
            _write_credentials(access_value, refresh_value, expires_in,
                               account_id or (existing or {}).get("account_id", ""),
                               account_hint or (existing or {}).get("account_hint", ""))
    except RuntimeError:
        raise
    except (OSError, PermissionError) as exc:
        raise RuntimeError(
            f"CREDENTIAL_STORE_FAILED: unable to save under {get_profile_dir()}. Cause: {exc}"
        ) from exc


def load_credentials() -> dict | None:
    paths = _cache_paths()
    cache_file = paths["cache"]
    if not cache_file.exists():
        return None
    try:
        data = json.loads(_load_cipher(paths).decrypt(cache_file.read_bytes()))
    except (InvalidToken, json.JSONDecodeError, ValueError) as exc:
        raise RuntimeError("CREDENTIAL_CACHE_CORRUPT: reconnect Outlook") from exc
    except (OSError, PermissionError) as exc:
        raise RuntimeError(f"CREDENTIAL_CACHE_READ_FAILED: {exc}") from exc
    if data.get("profile_id") != _profile_id():
        raise RuntimeError("USER_CONTEXT_MISMATCH: reconnect with the current user identity")
    return data


def clear_credentials():
    paths = _cache_paths()
    with _lock():
        for file_path in (
            paths["cache"],
            paths["key"],
            get_profile_dir() / "pending_device_code.json",
        ):
            try:
                file_path.unlink(missing_ok=True)
            except OSError as exc:
                raise RuntimeError(f"CREDENTIAL_CLEAR_FAILED: {file_path}. Cause: {exc}") from exc


def is_authenticated() -> bool:
    return load_credentials() is not None


def status() -> dict:
    data = load_credentials()
    if not data:
        return {"status": "NOT_CONNECTED"}
    if time.time() < data.get("expires_at", 0):
        return {"status": "CONNECTED", "expires_at": data.get("expires_at"),
                "account": data.get("account_hint", "")}
    try:
        get_valid_access()
        refreshed = load_credentials() or data
        return {"status": "CONNECTED", "expires_at": refreshed.get("expires_at"),
                "account": refreshed.get("account_hint", "")}
    except RuntimeError as exc:
        message = str(exc)
        if message.startswith("REAUTH_REQUIRED"):
            return {"status": "REAUTH_REQUIRED", "account": data.get("account_hint", "")}
        if message.startswith("TEMPORARY_ERROR"):
            return {"status": "TEMPORARY_ERROR", "account": data.get("account_hint", "")}
        raise


def _refresh_access(refresh_value: str) -> dict:
    tenant_id = _get_tenant_id()
    client_id = _get_client_id()
    if not tenant_id or not client_id:
        raise RuntimeError(
            "APP_CONFIG_REQUIRED: set MSGRAPH_TENANT_ID and MSGRAPH_DELEGATED_CLIENT_ID"
        )
    response = requests.post(
        TOKEN_URL.format(tenant=tenant_id),
        data={
            "grant_type": "refresh_token",
            "client_id": client_id,
            REFRESH_FIELD: refresh_value,
            "scope": GRAPH_SCOPE,
        },
        timeout=30,
    )
    response.raise_for_status()
    return response.json()


def get_valid_access() -> str:
    data = load_credentials()
    if data is None:
        raise RuntimeError("NOT_CONNECTED: run auth_login.py --request first")
    if time.time() < data.get("expires_at", 0):
        return data["access"]
    if not data.get("refresh"):
        raise RuntimeError("REAUTH_REQUIRED: no refresh credential")
    try:
        with _lock():
            latest = load_credentials() or data
            if time.time() < latest.get("expires_at", 0):
                return latest["access"]
            refreshed = _refresh_access(latest["refresh"])
            access_value = refreshed[ACCESS_FIELD]
            refresh_value = refreshed.get(REFRESH_FIELD, latest["refresh"])
            _write_credentials(access_value, refresh_value,
                               refreshed.get("expires_in", 3600),
                               latest.get("account_id", ""),
                               latest.get("account_hint", ""))
            return access_value
    except requests.HTTPError as exc:
        try:
            error_code = exc.response.json().get("error", "")
        except (ValueError, AttributeError):
            error_code = ""
        if error_code == "invalid_grant":
            raise RuntimeError("REAUTH_REQUIRED: Microsoft authorization expired") from exc
        raise RuntimeError("TEMPORARY_ERROR: refresh failed; retry later") from exc
    except RuntimeError:
        raise
    except Exception as exc:
        raise RuntimeError("TEMPORARY_ERROR: refresh failed; retry later") from exc


def _main():
    command = sys.argv[1] if len(sys.argv) > 1 else "status"
    try:
        if command == "logout":
            clear_credentials()
            print('{"status":"DISCONNECTED"}')
        elif command == "status":
            print(json.dumps(status(), ensure_ascii=False))
        else:
            print("Usage: token_manager.py [status|logout]", file=sys.stderr)
            return 2
        return 0
    except RuntimeError as exc:
        print(str(exc), file=sys.stderr)
        return 1


if __name__ == "__main__":
    raise SystemExit(_main())
